from rag_consumer import chunk_documents

request = {
    'documents': [
        {'document_id': 'd1', 'text': 'Hello world. This is a test.', 'metadata': {}}
    ],
    'strategy': 'sentence',
    'chunk_size': 120
}

result1 = chunk_documents(request)
result2 = chunk_documents(request)

for r1, r2 in zip(result1['records'], result2['records']):
    print(f'Run1 id={r1[\"chunk_id\"]}, Run2 id={r2[\"chunk_id\"]}, equal={r1[\"chunk_id\"] == r2[\"chunk_id\"]}')

# Different documents should have different chunk ids
request2 = {
    'documents': [
        {'document_id': 'd2', 'text': 'Hello world. This is a test.', 'metadata': {}}
    ],
    'strategy': 'sentence',
    'chunk_size': 120
}
result3 = chunk_documents(request2)
assert result1['records'][0]['chunk_id'] != result3['records'][0]['chunk_id']
print('Different documents have different chunk IDs ✓')
"

